{"version":3,"file":"preload.js","sources":["../electron/preload.ts"],"sourcesContent":["// import { ipcRenderer, contextBridge } from 'electron'\n\n// // --------- Expose some API to the Renderer process ---------\n// contextBridge.exposeInMainWorld('ipcRenderer', {\n//   on(...args: Parameters<typeof ipcRenderer.on>) {\n//     const [channel, listener] = args\n//     return ipcRenderer.on(channel, (event, ...args) => listener(event, ...args))\n//   },\n//   off(...args: Parameters<typeof ipcRenderer.off>) {\n//     const [channel, ...omit] = args\n//     return ipcRenderer.off(channel, ...omit)\n//   },\n//   send(...args: Parameters<typeof ipcRenderer.send>) {\n//     const [channel, ...omit] = args\n//     return ipcRenderer.send(channel, ...omit)\n//   },\n//   invoke(...args: Parameters<typeof ipcRenderer.invoke>) {\n//     const [channel, ...omit] = args\n//     return ipcRenderer.invoke(channel, ...omit)\n//   },\n\n//   // You can expose other APTs you need here.\n//   // ...\n// })\n\n\nconst { contextBridge, ipcRenderer } = require('electron')\n\n// Expose protected methods that allow the renderer process to use\n// the ipcRenderer without exposing the entire object\ncontextBridge.exposeInMainWorld('ipcRenderer', {\n  on(...args: Parameters<typeof ipcRenderer.on>) {\n    const [channel, listener] = args\n    return ipcRenderer.on(channel, (event: any, ...args: any[]) => (listener as any)(event, ...args))\n  },\n  off(...args: Parameters<typeof ipcRenderer.off>) {\n    const [channel, ...omit] = args\n    return ipcRenderer.off(channel, ...omit)\n  },\n  send(...args: Parameters<typeof ipcRenderer.send>) {\n    const [channel, ...omit] = args\n    return ipcRenderer.send(channel, ...omit)\n  },\n  invoke(...args: Parameters<typeof ipcRenderer.invoke>) {\n    const [channel, ...omit] = args\n    return ipcRenderer.invoke(channel, ...omit)\n  },\n})\n\n// Specifically expose DRM and Secure Storage APIs for clarity in the renderer\ncontextBridge.exposeInMainWorld('drmApi', {\n  decryptCDC: (container: any, passKey: string) => ipcRenderer.invoke('drm:decrypt-cdc', container, passKey),\n  decryptPayload: (container: any, contentKey: string) => ipcRenderer.invoke('drm:decrypt-payload', container, contentKey),\n  setSecureData: (docId: string, key: string, value: string) => ipcRenderer.invoke('secure:set-data', docId, key, value),\n  getSecureData: (docId: string, key: string) => ipcRenderer.invoke('secure:get-data', docId, key),\n  removeDocData: (docId: string) => ipcRenderer.invoke('secure:remove-doc-data', docId),\n  // File & List Persistence\n  saveList: (documents: any[]) => ipcRenderer.invoke('docs:save-list', documents),\n  loadList: () => ipcRenderer.invoke('docs:load-list'),\n  saveFileLocally: (docId: string, fileName: string, arrayBuffer: ArrayBuffer) => ipcRenderer.invoke('docs:save-file-locally', docId, fileName, arrayBuffer),\n  readLocalFile: (localPath: string) => ipcRenderer.invoke('docs:read-local-file', localPath),\n  convertToPdf: (docId: string, base64Data: string, originalName: string, originalMime: string) => ipcRenderer.invoke('drm:convert-office-to-pdf', docId, base64Data, originalName, originalMime),\n})\n\ncontextBridge.exposeInMainWorld('confiShare', {\n  openFile: (path: string, passKey?: string) => ipcRenderer.invoke('open-cdc-file', path, passKey),\n  closeSession: (sessionDir: string) => ipcRenderer.invoke('close-cdc-session', sessionDir),\n})\r\n"],"names":["args"],"mappings":"AA0BA,MAAM,EAAE,eAAe,gBAAgB,QAAQ,UAAU;AAIzD,cAAc,kBAAkB,eAAe;AAAA,EAC7C,MAAM,MAAyC;AAC7C,UAAM,CAAC,SAAS,QAAQ,IAAI;AAC5B,WAAO,YAAY,GAAG,SAAS,CAAC,UAAeA,UAAiB,SAAiB,OAAO,GAAGA,KAAI,CAAC;AAAA,EAClG;AAAA,EACA,OAAO,MAA0C;AAC/C,UAAM,CAAC,SAAS,GAAG,IAAI,IAAI;AAC3B,WAAO,YAAY,IAAI,SAAS,GAAG,IAAI;AAAA,EACzC;AAAA,EACA,QAAQ,MAA2C;AACjD,UAAM,CAAC,SAAS,GAAG,IAAI,IAAI;AAC3B,WAAO,YAAY,KAAK,SAAS,GAAG,IAAI;AAAA,EAC1C;AAAA,EACA,UAAU,MAA6C;AACrD,UAAM,CAAC,SAAS,GAAG,IAAI,IAAI;AAC3B,WAAO,YAAY,OAAO,SAAS,GAAG,IAAI;AAAA,EAC5C;AACF,CAAC;AAGD,cAAc,kBAAkB,UAAU;AAAA,EACxC,YAAY,CAAC,WAAgB,YAAoB,YAAY,OAAO,mBAAmB,WAAW,OAAO;AAAA,EACzG,gBAAgB,CAAC,WAAgB,eAAuB,YAAY,OAAO,uBAAuB,WAAW,UAAU;AAAA,EACvH,eAAe,CAAC,OAAe,KAAa,UAAkB,YAAY,OAAO,mBAAmB,OAAO,KAAK,KAAK;AAAA,EACrH,eAAe,CAAC,OAAe,QAAgB,YAAY,OAAO,mBAAmB,OAAO,GAAG;AAAA,EAC/F,eAAe,CAAC,UAAkB,YAAY,OAAO,0BAA0B,KAAK;AAAA;AAAA,EAEpF,UAAU,CAAC,cAAqB,YAAY,OAAO,kBAAkB,SAAS;AAAA,EAC9E,UAAU,MAAM,YAAY,OAAO,gBAAgB;AAAA,EACnD,iBAAiB,CAAC,OAAe,UAAkB,gBAA6B,YAAY,OAAO,0BAA0B,OAAO,UAAU,WAAW;AAAA,EACzJ,eAAe,CAAC,cAAsB,YAAY,OAAO,wBAAwB,SAAS;AAAA,EAC1F,cAAc,CAAC,OAAe,YAAoB,cAAsB,iBAAyB,YAAY,OAAO,6BAA6B,OAAO,YAAY,cAAc,YAAY;AAChM,CAAC;AAED,cAAc,kBAAkB,cAAc;AAAA,EAC5C,UAAU,CAAC,MAAc,YAAqB,YAAY,OAAO,iBAAiB,MAAM,OAAO;AAAA,EAC/F,cAAc,CAAC,eAAuB,YAAY,OAAO,qBAAqB,UAAU;AAC1F,CAAC;"}}